@article{maSiftUsingRefinementguided,
 title = {Sift: {{Using Refinement-guided Automation}} to {{Verify Complex Distributed Systems}}},
 author = {Ma, Haojun and Ahmad, Hammad and Goel, Aman and Goldweber, Eli and Jeannin, Jean-Baptiste and Kapritsos, Manos and Kasikci, Baris},
 date = {2022},
 file = {/Users/stevenschaefer/Zotero/storage/YPMT6F2V/Ma et al. - Sift Using Refinement-guided Automation to Verify.pdf},
 langid = {english},
 abstract = {Distributed systems are hard to design and implement correctly. Recent work has tried to use formal verification techniques to provide rigorous correctness guarantees. These works present a hard choice, though. One must either opt for the power of refinement-based approaches like IronFleet and Verdi, at the cost of large amounts of manual effort; or choose the more automated approach of I4, IC3PO, SWISS and DistAI which give up the ability to prove refinement and the power and scalability that come with it.}
}

@article{yaoDistAIDataDrivenAutomated,
 title = {{{DistAI}}: {{Data-Driven Automated Invariant Learning}} for {{Distributed Protocols}}},
 author = {Yao, Jianan and Tao, Runzhou and Gu, Ronghui and Nieh, Jason and Jana, Suman and Ryan, Gabriel},
 date = {2021},
 file = {/Users/stevenschaefer/Zotero/storage/QECYBHLP/Yao et al. - DistAI Data-Driven Automated Invariant Learning f.pdf},
 langid = {english},
 abstract = {Distributed systems are notoriously hard to implement correctly due to non-determinism. Finding the inductive invariant of the distributed protocol is a critical step in verifying the correctness of distributed systems, but takes a long time to do even for simple protocols. We present DistAI, a data-driven automated system for learning inductive invariants for distributed protocols. DistAI generates data by simulating the distributed protocol at different instance sizes and recording states as samples. Based on the observation that invariants are often concise in practice, DistAI starts with small invariant formulas and enumerates all strongest possible invariants that hold for all samples. It then feeds those invariants and the desired safety properties to an SMT solver to check if the conjunction of the invariants and the safety properties is inductive. Starting with small invariant formulas and strongest possible invariants avoids large SMT queries, improving SMT solver performance. Because DistAI starts with the strongest possible invariants, if the SMT solver fails, DistAI does not need to discard failed invariants, but knows to monotonically weaken them and try again with the solver, repeating the process until it eventually succeeds. We prove that DistAI is guaranteed to find the ∃-free inductive invariant that proves the desired safety properties in finite time, if one exists. Our evaluation shows that DistAI successfully verifies 13 common distributed protocols automatically and outperforms alternative methods both in the number of protocols it verifies and the speed at which it does so, in some cases by more than two orders of magnitude.}
}

@article{hanceFindingInvariantsDistributed,
 title = {Finding {{Invariants}} of {{Distributed Systems}}: {{It}}’s a {{Small}} ({{Enough}}) {{World After All}}},
 author = {Hance, Travis and Heule, Marijn and Martins, Ruben and Parno, Bryan},
 date = {2021},
 file = {/Users/stevenschaefer/Zotero/storage/S77U7QUW/Hance et al. - Finding Invariants of Distributed Systems It’s a .pdf},
 langid = {english},
 abstract = {Today’s distributed systems are increasingly complex, leading to subtle bugs that are difficult to detect with standard testing methods. Formal verification can provably rule out such bugs, but historically it has been excessively labor intensive. For distributed systems, recent work shows that, given a correct inductive invariant, nearly all other proof work can be automated; however, the construction of such invariants is still a difficult manual task. In this paper, we demonstrate a new methodology for automating the construction of inductive invariants, given as input a (formal) description of the distributed system and a desired safety condition. Our system performs an exhaustive search within a given space of candidate invariants in order to find and verify inductive invariants which suffice to prove the safety condition. Central to our ability to search efficiently is our algorithm’s ability to learn from counterexamples whenever a candidate fails to be invariant, allowing us to check the remaining candidates more efficiently. We hypothesize that many distributed systems, even complex ones, may have concise invariants that make this approach practical, and in support of this, we show that our system is able to identify and verify inductive invariants for the Paxos protocol, which proved too complex for previous work.}
}

@article{goelRegularityQuantificationNew,
 title = {Regularity and {{Quantiﬁcation}}: {{A New Approach}} to {{Verify Distributed Protocols}}},
 author = {Goel, Aman and Sakallah, Karem A},
 date = {2021},
 pages = {23},
 file = {/Users/stevenschaefer/Zotero/storage/LMSAIKBM/Goel and Sakallah - Regularity and Quantiﬁcation A New Approach to Ve.pdf},
 langid = {english},
 abstract = {Proving that an unbounded distributed protocol satisfies a given safety property amounts to finding a quantified inductive invariant that implies the property for all possible instance sizes of the protocol. Existing methods for solving this problem can be described as search procedures for an invariant whose quantification prefix fits a particular template. We propose an alternative constructive approach that does not prescribe, a priori, a specific quantifier prefix. Instead, the required prefix is automatically inferred without any enumerative search by carefully analyzing the spatial and temporal regularity of the protocol. The key insight underlying this approach is that structural regularity and quantification are closely related concepts that express protocol invariance under different re-arrangements of its components and its unbounded evolution over time. We extended the finite-domain IC3/PDR algorithm to use these regularities and boost clause learning to automatically derive the required quantified inductive invariant by exploiting the connection between structural regularities and quantification. We also describe a procedure to automatically find a minimal finite size, the cutoff, that yields a quantified invariant proving safety for any size. Our approach is implemented in IC3PO, a new verifier for distributed protocols that significantly outperforms the state-of-the-art, scales orders of magnitude faster, and robustly derives compact inductive invariants fully automatically.}
}

@book{bradleySATBasedModelChecking2011,
 title = {{{SAT-Based Model Checking}} without {{Unrolling}}},
 author = {Bradley, Aaron},
 date = {2011-01-23},
 isbn = {978-3-642-18274-7},
 doi = {10.1007/978-3-642-18275-4_7},
 pages = {87},
 pagetotal = {70},
 abstract = {A new form of SAT-based symbolic model checking is de- scribed. Instead of unrolling the transition relation, it incrementally gen- erates clauses that are inductive relative to (and augment) stepwise ap- proximate reachability information. In this way, the algorithm gradually refines the property, eventually producing either an inductive strengthen- ing of the property or a counterexample trace. Our experimental studies show that induction is a powerful tool for generalizing the unreachability of given error states: it can refine away many states at once, and it is effective at focusing the proof search on aspects of the transition system relevant to the property. Furthermore, the incremental structure of the algorithm lends itself to a parallel implementation.}
}

